<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cat FAQ - All About Felines</title>
    <style>
        :root {
            --bg-color: #121212;
            --surface-color: #1e1e1e;
            --primary-color: #bb86fc;
            --text-primary: #e0e0e0;
            --text-secondary: #a0a0a0;
            --border-color: #333;
            --focus-outline: #03dac6;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-primary);
            margin: 0;
            padding: 2rem;
            display: flex;
            justify-content: center;
            line-height: 1.6;
        }

        main {
            width: 100%;
            max-width: 800px;
        }

        h1 {
            text-align: center;
            color: var(--primary-color);
            margin-bottom: 2rem;
        }

        .faq-container {
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .example {
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
            transition: border-color 0.2s;
        }

        .example:hover {
            border-color: var(--primary-color);
        }

        .example h3 {
            margin: 0;
        }

        .faq-trigger {
            width: 100%;
            text-align: left;
            background: none;
            border: none;
            color: var(--text-primary);
            padding: 1.25rem;
            font-size: 1.1rem;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
            outline: none;
        }

        .faq-trigger:focus-visible {
            box-shadow: inset 0 0 0 2px var(--focus-outline);
        }

        .faq-trigger::after {
            content: '+';
            font-size: 1.5rem;
            color: var(--primary-color);
            transition: transform 0.3s;
        }

        .faq-trigger[aria-expanded="true"]::after {
            transform: rotate(45deg);
        }

        .details {
            padding: 0 1.25rem 1.25rem 1.25rem;
            color: var(--text-secondary);
            border-top: 1px solid var(--border-color);
            animation: slideDown 0.3s ease-out;
        }

        .details[hidden] {
            display: none;
        }

        @keyframes slideDown {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Responsive adjustments */
        @media (max-width: 600px) {
            body {
                padding: 1rem;
            }
        }
    </style>
</head>
<body>
    <main id="root">
        <!-- React-style components will render here -->
    </main>

    <script>
        // "React-style" components implemented as pure functions returning HTML strings

        const FAQItem = ({ question, answer, id }) => {
            return `
                <div class="example">
                    <h3>
                        <button 
                            type="button" 
                            class="faq-trigger" 
                            id="trigger-${id}"
                            aria-controls="panel-${id}"
                            aria-expanded="false"
                        >
                            ${question}
                        </button>
                    </h3>
                    <div 
                        class="details" 
                        id="panel-${id}"
                        role="region"
                        aria-labelledby="trigger-${id}"
                        hidden
                    >
                        <p>${answer}</p>
                    </div>
                </div>
            `;
        };

        const FAQList = (items) => {
            return `
                <div class="faq-container">
                    ${items.map((item, index) => FAQItem({ ...item, id: index })).join('')}
                </div>
            `;
        };

        const App = () => {
            const faqData = [
                {
                    question: "Why do cats purr?",
                    answer: "Cats purr for many reasons, including contentment, stress relief, and communication. It's also believed that the frequency of a cat's purr can help improve bone density and promote healing."
                },
                {
                    question: "Why do cats have whiskers?",
                    answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents, and determine if they can fit through tight spaces."
                },
                {
                    question: "Why do cats sleep so much?",
                    answer: "As natural predators, cats conserve energy for hunting. They spend an average of 12 to 16 hours a day sleeping to stay alert for their next 'burst' of activity."
                },
                {
                    question: "Why do cats knead (make biscuits)?",
                    answer: "Kneading is a behavior cats carry over from kittenhood, when they would knead their mothers to stimulate milk flow. In adults, it's often a sign of comfort and security."
                },
                {
                    question: "Why do cats always land on their feet?",
                    answer: "Cats have a 'righting reflex'—an innate ability to orient themselves as they fall. Their flexible backbone and lack of a functional collarbone allow them to twist their bodies mid-air."
                }
            ];

            return `
                <h1>Feline Frequently Asked Questions</h1>
                ${FAQList(faqData)}
            `;
        };

        // Initialize the "App"
        const root = document.getElementById('root');
        root.innerHTML = App();

        // Disclosure Widget Logic
        const initDisclosures = () => {
            const triggers = document.querySelectorAll('.faq-trigger');

            triggers.forEach(trigger => {
                const panel = document.getElementById(trigger.getAttribute('aria-controls'));

                trigger.addEventListener('click', () => {
                    const isExpanded = trigger.getAttribute('aria-expanded') === 'true';

                    // Toggle state
                    trigger.setAttribute('aria-expanded', !isExpanded);
                    panel.hidden = isExpanded;
                });
            });
        };

        initDisclosures();
    </script>
</body>
</html>
