const App = () => {
    const faqData = [
        {
            question: "Why do cats purr?",
            answer: "Cats purr for many reasons, including contentment, stress relief, and communication. It's also believed that the frequency of a cat's purr can help improve bone density and promote healing."
        },
        {
            question: "Why do cats have whiskers?",
            answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents, and determine if they can fit through tight spaces."
        },
        {
            question: "Why do cats sleep so much?",
            answer: "As natural predators, cats conserve energy for hunting. They spend an average of 12 to 16 hours a day sleeping to stay alert for their next 'burst' of activity."
        },
        {
            question: "Why do cats knead (make biscuits)?",
            answer: "Kneading is a behavior cats carry over from kittenhood, when they would knead their mothers to stimulate milk flow. In adults, it's often a sign of comfort and security."
        },
        {
            question: "Why do cats always land on their feet?",
            answer: "Cats have a 'righting reflex'—an innate ability to orient themselves as they fall. Their flexible backbone and lack of a functional collarbone allow them to twist their bodies mid-air."
        }
    ];

    return `
        <h1 id="main-content">Feline Frequently Asked Questions</h1>
        ${FAQList(faqData)}
    `;
};

// Initialize the "App"
const root = document.getElementById('root');
root.innerHTML = App();

// Disclosure Widget Logic
const initDisclosures = () => {
    const triggers = document.querySelectorAll('.faq-trigger');

    triggers.forEach(trigger => {
        const panel = document.getElementById(trigger.getAttribute('aria-controls'));

        // Initialize state: collapsed by default
        trigger.setAttribute('aria-expanded', 'false');
        panel.hidden = true;

        trigger.addEventListener('click', () => {
            const isExpanded = trigger.getAttribute('aria-expanded') === 'true';

            // Toggle state
            trigger.setAttribute('aria-expanded', !isExpanded);
            panel.hidden = isExpanded;
        });
    });
};

initDisclosures();

