                         role="region"
                         aria-labelledby="trigger-${id}"
                     >
                         <p>${answer}</p>
                     </div>
                 </div>
             `;
         };

         const FAQList = (items) => {
             return `
                 <div class="faq-container">
                     ${items.map((item, index) => FAQItem({ ...item, id: index })).join('')}
                 </div>
             `;
         };

