            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
            transition: border-color 0.2s;
        }

        .example:hover {
            border-color: var(--primary-color);
        }

        .example h3 {
            margin: 0;
        }

        .faq-trigger {
            width: 100%;
            text-align: left;
            background: none;
            border: none;
            color: var(--text-primary);
            padding: 1.25rem;
            font-size: 1.1rem;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
            outline: none;
