            margin-bottom: 2rem;
        }

        .faq-container {
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .example {
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
            transition: border-color 0.2s;
        }

        .example:hover {
            border-color: var(--primary-color);
        }

        .example h2 {
            margin: 0;
